## 10. Pseudo-código del mechanism (especificación ilustrativa — NO ejecutada)

```python
# CycleNet: per-phase cycle aggregation + phase-shared linear forecaster + residual
# C = cycle length; d = phase-embedding dim; L = input len; H = horizon
def build(global_series_train):          # D1: promedio de canales sobre TRAIN split
    return (global_series_train - mu_G) / sd_G          # D3: escala con stats de train

class CycleNet:
    E = param(C, d)                       # cycle pattern APRENDIDO, una fila por fase
    W = param(C, 2*d, H); b = param(C, H) # W[phi] -> sólo la fase phi participa
    R = param(2*L, H)                     # rama residual (tendencia/no periódico)
    scale, shift = param(N), param(N)     # affine por canal (D6: sharing entre canales)

def forward(x_BLC, ctx_BLC):              # ctx = segmentos alineados de global series
    mu = x.mean(1); sd = x.std(1) + eps
    xn = (x - mu) / sd                    # RevIN por instancia
    xc = gather_by_phase(xn, C)           # P_p = media de los t con t mod C == p
    g  = gather_by_phase(ctx, C)          # contexto medio por fase (compartido, canal-agnóstico)
    z  = concat([E[phases], g_embed(g)])  # (C, 2d)
    y  = einsum('cpd,cph->ch', z, W) + b                        # ciclo: SOLO su fase
    y += einsum('bl,lh->bh', concat([xn, diff(xn)]), R)          # residual
    y  = y * scale + shift
    return y * sd + mu                    # inverse RevIN

def train_epoch(batch):
    yhat = model(x, ctx_from_train_only_global_series(t_start))  # D2: sin futuro
    loss = mse(yhat, y) + LAMBDA * within_phase_variance(yhat, phases)   # D4
    loss.backward(); clip(1.0); opt.step()
# Selección: C* por ACF en TRAIN (+ prior de dominio, D5); lambda y early-stop en VAL.
# Invariante anti-fuga assert: max(timestamp(ctx)) <= t_input_end
```

